14	function formatShaderString(str) {
15	  // This function:
16	  // A) removes whitespace lines at the beginning of the string
17	  // B) removes unnecessary spaces from the beginning of each line
18	
19	  const lines = str.split("\n");
20	  let firstLineIdx;
21	  for (firstLineIdx = 0; firstLineIdx < lines.length; firstLineIdx++) {
22	    if (lines[firstLineIdx].match(/\S/)) {
23	      // Found the first line that's not entirely whitespace
24	      break;
25	    }
26	  }
27	  if (firstLineIdx === lines.length) {
28	    // All lines are empty
29	    return "";
30	  }
31	
32	  let finalStr = "";
33	  const pattern = /^\s*/;
34	  const firstLine = lines[firstLineIdx];
35	  const spacesInFrontOfFirstLine = firstLine.match(pattern)[0].length;
36	  for (let i = firstLineIdx; i < lines.length; i++) {
37	    let line = lines[i];
38	    const spacesInFront = line.match(pattern)[0].length;
39	    if (spacesInFront >= spacesInFrontOfFirstLine) {
40	      line = line.slice(spacesInFrontOfFirstLine);
41	    }
42	    finalStr += `${line}\n`;
43	  }
44	  return finalStr;
45	}
