87	      that._getPrimitiveFunctions.push(getPrimitiveFunction);
88	    }
89	
90	    const knock = knockout.observable();
91	    knockout.defineProperty(that, name, {
92	      get: function () {
93	        return knock();
94	      },
95	      set: function (value) {
96	        // Convert input values to the correct type
97	        if (typeof initialValue === "number" && typeof value === "string") {
98	          value = Number(value);
99	          if (isNaN(value)) {
100	            value = initialValue;
101	          }
102	        }
103	        if (typeof initialValue === "boolean" && typeof value === "number") {
104	          value = value === 0 ? true : false;
105	        }
