37	    let line = lines[i];
38	    const spacesInFront = line.match(pattern)[0].length;
39	    if (spacesInFront >= spacesInFrontOfFirstLine) {
40	      line = line.slice(spacesInFrontOfFirstLine);
41	    }
42	    finalStr += `${line}\n`;
43	  }
44	  return finalStr;
