804	/**
805	 * Handles key press events on the shader editor.
806	 */
807	VoxelInspectorViewModel.prototype.shaderEditorKeyPress = function (
808	  sender,
809	  event,
810	) {
811	  if (event.keyCode === 9) {
812	    //tab
813	    event.preventDefault();
814	    const textArea = event.target;
815	    const start = textArea.selectionStart;
816	    const end = textArea.selectionEnd;
817	    let newEnd = end;
818	    const selected = textArea.value.slice(start, end);
819	    const lines = selected.split("\n");
820	    const length = lines.length;
821	    let i;
822	    if (!event.shiftKey) {
823	      for (i = 0; i < length; ++i) {
824	        lines[i] = `  ${lines[i]}`;
825	        newEnd += 2;
826	      }
827	    } else {
828	      for (i = 0; i < length; ++i) {
829	        if (lines[i][0] === " ") {
830	          if (lines[i][1] === " ") {
831	            lines[i] = lines[i].substr(2);
832	            newEnd -= 2;
833	          } else {
834	            lines[i] = lines[i].substr(1);
835	            newEnd -= 1;
836	          }
837	        }
838	      }
839	    }
840	    const newText = lines.join("\n");
841	    textArea.value =
842	      textArea.value.slice(0, start) + newText + textArea.value.slice(end);
843	    textArea.selectionStart = start !== end ? start : newEnd;
844	    textArea.selectionEnd = newEnd;
845	  } else if (event.ctrlKey && (event.keyCode === 10 || event.keyCode === 13)) {
846	    //ctrl + enter
847	    this.compileShader();
848	  }
849	  return true;
850	};
